<script setup>
import {Check,Plus,ChevronRight,X} from '@lucide/vue';import {levelLabel} from '../lib/spells';
defineProps({spells:Array,selectedId:Number,pendingIds:{type:Array,default:()=>[]},preparing:Boolean});defineEmits(['select','toggle']);
</script>
<template><div class="spell-table"><div class="table-heading"><span>Magia</span><span>Escola</span><span>{{preparing?'Preparação':'Conjuração'}}</span></div><div v-for="spell in spells" :key="spell.id" class="spell-row" :class="{selected:selectedId===spell.id}"><button class="spell-name-button" @click="$emit('select',spell.id)"><span class="circle-number" :title="levelLabel(spell.level)">{{spell.level===0?'T':spell.level}}</span><span><strong>{{spell.name}}</strong><small>{{levelLabel(spell.level)}}<template v-if="spell.sourceKind==='homebrew'"> · Homebrew</template></small></span><ChevronRight :size="16" class="row-chevron"/></button><span class="school-cell">{{spell.school}}</span><div class="row-end"><button v-if="preparing" class="prepare-button" :class="{prepared:spell.isPrepared}" :disabled="pendingIds.includes(spell.id)||(!spell.isPrepared&&!spell.canPrepare)" :aria-label="`${spell.isPrepared?'Remover':'Preparar'} ${spell.name}`" :title="spell.canPrepare||spell.isPrepared?'':'Fora da lista da classe do personagem'" @click="$emit('toggle',spell)"><Check v-if="spell.isPrepared" :size="16"/><Plus v-else :size="16"/><span>{{pendingIds.includes(spell.id)?'Salvando…':spell.isPrepared?'Preparada':spell.canPrepare?'Preparar':'Outra classe'}}</span></button><template v-else><span class="casting-cell">{{spell.castingTime}}</span><button class="icon-button remove-button" :disabled="pendingIds.includes(spell.id)" :aria-label="`Remover ${spell.name} das preparadas`" @click="$emit('toggle',spell)"><X :size="16"/></button></template></div></div></div></template>